 public void AdoptReconnectedScene(FaceScene next){var old=Scene;if(old!=null){if(old.TextureRoot!=null)next.SetTextureRoot(old.TextureRoot);foreach(var p in old.Parts.Where(p=>p.ManualTexturePath!=null)){var match=next.Parts.FirstOrDefault(n=>n.Name==p.Name&&n.HeadPartId==p.HeadPartId);if(match!=null)try{next.SetTexture(match,p.ManualTexturePath!,true);}catch(Exception e){throw new InvalidDataException("Manual DDS could not be restored; previous face retained: "+e.Message);}}}var accepted=new List<Binding>();foreach(var b in bindings){var oldPart=old?.Parts.FirstOrDefault(p=>p.Name==b.Part&&p.Source==b.Nif);var match=next.Parts.FirstOrDefault(p=>p.Name==b.Part&&p.HeadPartId==oldPart?.HeadPartId);if(match==null)continue;try{next.AttachTri(match,TriFace.Read(b.Tri),false);accepted.Add(b with{Nif=match.Source,Confirmed=false,NifHash=Hash(match.Source)});}catch(Exception e){next.Warnings.Add("TRI rebind: "+e.Message);}}Scene=next;bindings.Clear();bindings.AddRange(accepted);Notify();}

